"""Export current measured M0 evidence. Never infer successful checks from file names."""
import hashlib, json, pathlib, re, shutil, subprocess
from acquire import ROOT, digest

def read(relative):return json.loads((ROOT/relative).read_text(encoding='utf-8-sig'))
def main():
    docs=ROOT/'docs/implementation';evidence=docs/'evidence';evidence.mkdir(exist_ok=True)
    sources=read('cmake/sources.lock.json');recipes=read('cmake/port-recipes.lock.json');tools=read('cmake/tools.lock.json')
    independent=read('.cache/independent-checks.json');clean=read('.cache/clean-checkout.json');package=read('.cache/clean-package.json')
    native={profile:read('.cache/native-'+profile+'.json') for profile in ['m0-debug','m0-relwithdebinfo','m0-release']}
    clean_root=pathlib.Path(clean['checkout']);native['clean-release']=json.loads((clean_root/'.cache/native-m0-release.json').read_text())
    first=read('.cache/bootstrap-final-first.json');second=read('.cache/bootstrap-final-second.json')
    prefetches=[read('.cache/prefetch-final-first.json'),read('.cache/prefetch-final-second.json')]
    amplitude=read('.cache/amplitude-native-result.json');import_result=read('.cache/amplitude-verification.json')
    # Accept Debug's intentionally excluded packaging entry, but no failed/blocked native gate.
    failures=[(name,row) for name,rows in native.items() for row in rows if row.get('status') in ['failed','blocked']]
    failures += [('bootstrap',row) for row in first+second if row['exit_code']!=0]
    failures += [('independent',row) for row in independent if row['status']!='passed']
    failures += [('prefetch',row) for row in prefetches if row['status']!='passed']
    failures += [('amplitude',row) for row in amplitude+import_result if row['exit_code']!=0]
    if failures:raise RuntimeError('Cannot mark M0 verified: '+str(failures))
    if package['source_checkout_git_status_after']:raise RuntimeError('Clean checkout changed after restoration')
    if digest(ROOT/package['file'])!=package['sha256']:raise RuntimeError('Clean package was changed after validation')

    def export_log(path,name=None):
        source=ROOT/path
        if source.is_file():
            target=evidence/(name or source.name)
            text=source.read_text(encoding='utf-8',errors='replace')
            text=text.replace(str(ROOT),'${PROJECT_ROOT}').replace(ROOT.as_posix(),'${PROJECT_ROOT}')
            # Keep commands and results, but avoid committing user-specific runtime directories.
            home=str(pathlib.Path.home());text=text.replace(home,'${USERPROFILE}').replace(home.replace('\\','/'),'${USERPROFILE}')
            target.write_text(text,encoding='utf-8')
    for profile,rows in native.items():
        for row in rows:
            if row.get('log'):
                if profile=='clean-release':
                    path=(clean_root/row['log']).relative_to(ROOT)
                    export_log(path,'clean-'+path.name)
                else:export_log(row['log'])
    for path in ['.cache/vcpkg-plan.log','.cache/vcpkg-prefetch.log','.cache/headless-pe-dependents.log','.cache/amplitude-deps.log','.cache/amplitude-configure.log','.cache/amplitude-build.log','.cache/amplitude-install.log','.cache/amplitude-recipe.patch']:
        export_log(path)
    for row in import_result:
        if row.get('log'):export_log(row['log'])
    for row in second:
        if row.get('log'):export_log(row['log'],'bootstrap-'+pathlib.Path(row['log']).name)
    archive_status=read('.cache/acquisition-port-assets.json')
    if any(row['status']!='acquired' for row in archive_status):raise RuntimeError('An archive is not acquired')
    port_inventory=[]
    for port in recipes['ports']:
        name=port['name'];tested=name in ['flecs','luau','sqlite3']
        sdk_dep=name in ['flatbuffers','lz4','dylib','eigen3','xsimd','miniaudio']
        port_inventory.append({**port,'acquisition':'acquired','status':'integrated' if tested else 'build-verified' if sdk_dep else 'acquired','native_build':'build-verified' if tested or sdk_dep else 'not built for later integration','integration':'M0 isolated probe' if tested else 'Amplitude private build/import dependency' if sdk_dep else 'not integrated','active':port.get('active',True)})
    source_inventory=[]
    for source in sources['sources']:
        source_inventory.append({**source,'status':'build-verified' if source['name']=='amplitude' else 'acquired','acquisition':'acquired','native_build':'static Release /MD build/install and imported-target link/run passed' if source['name']=='amplitude' else 'not built','integration':'no device/service acceptance' if source['name']=='amplitude' else 'not integrated','acceptance_gate':'pending architecture gate' if not source.get('active',True) else 'later subsystem integration'})
    inventory={'schema':1,'resolved_on':'2026-10-07','vcpkg_checkout_and_baseline':sources['vcpkg_commit'],'ports':port_inventory,'source_exceptions':source_inventory,'effekseer':{'version':'1.80.7','status':'acquired','runtime':'official EffekseerForCpp1.80.7.zip','authoring':'official Effekseer1.80.7Win.zip','integration':'not built/validated as a renderer adapter'},'eos':{'version':'1.19.2.1','status':'acquired','origin':'authorized user download','integration':'not build-tested/online-tested'},'npm':{'mcp':'1.32.1','gltf_validator':'2.0.0-dev.3.10','status':'acquired','verification':'exact npm ci lockfiles plus imports/validator fixture; no bridge endpoint'},'inactive_python_wheels':read('cmake/candidate-python.lock.json')}
    (docs/'dependencies.json').write_text(json.dumps(inventory,indent=2)+'\n')
    measured={'schema':1,'source_revision_verified_clean':clean['source_commit'],'environment':read('.cache/environment.json')['os'],'native':native,'bootstrap_first':first,'bootstrap_second':second,'prefetch':prefetches,'independent':independent,'amplitude_build_install':amplitude,'amplitude_import':import_result,'package':package}
    # Absolute SDK locations are deliberately absent; commands are normalized for portability.
    text=json.dumps(measured,indent=2)
    for prefix,replacement in [(str(ROOT),'${PROJECT_ROOT}'),(ROOT.as_posix(),'${PROJECT_ROOT}'),(str(pathlib.Path.home()),'${USERPROFILE}')]:text=text.replace(prefix.replace('\\','\\\\'),replacement).replace(prefix,replacement)
    (evidence/'verification.json').write_text(text+'\n')

    lines=['# M0 project bootstrap report','','M0 is verified on Windows x64. Project root: `C:\\DarkAngel`. Prepared and resolved 7 October 2026 (Europe/Copenhagen). M1 has not started.','','The small C++20 shell and real Flecs/Luau/SQLite probes pass in Debug, RelWithDebInfo and Release. A separate clean Git checkout of revision `'+clean['source_commit']+'` also configured, built, passed CTest, rebuilt incrementally and produced a relocatable ZIP. Existing verified tools/source archives were reused through junctions; dependency libraries rebuilt where the ABI/cache key differed. This is clean source-checkout verification, not a clean-machine/device qualification or a bit-for-bit native reproducibility claim.','','## Project and targets','','The repository contains `cmake/`, bounded bootstrap/verification scripts, static Foundation and bootstrap Runtime libraries, `apps/headless/`, real tests, reserved gameplay/editor/cooker/agent folders, Ashen Roots README, pinned source exceptions, complete architecture inputs, notices and evidence. Local tools, caches, SDKs, build/stage output, npm installs and machine SDK configuration are ignored. The original user files and EOS SDK remain intact. No external repository, push, publication or deployment was created.','','Targets: `DarkAngelFoundation`, `DarkAngelRuntime`, `DarkAngelHeadless`, `FlecsProbe`, `LuauProbe`, `SQLiteProbe`. The Amplitude import proof is an optional standalone support check, with no SDK/audio linkage added to Headless.','','The complete supplied decision log is retained as DOCX and a faithful ordered searchable extraction (1,308 paragraph/table-row records, 1,388 source text nodes). Tables, statuses, complete decision records and caveats are retained; the extraction is not a summary.','','## Frozen toolchain','','| Tool | Exact selected version | Verification |','|---|---|---|','| Visual Studio | 2026 Community 18.10.3 / 18.10.12224.181 | User-installed; supported vswhere detection |','| MSVC | toolset directory 14.51.36231; serviced compiler 19.51.36260.0/linker 14.51.36260.0 | Executable hashes and /Bv compile proof |','| Windows SDK | 10.0.26100.0 | Scoped compiler environment and actual native builds |','| CMake / CTest / CPack | 4.4.4 | Official Windows ZIP digest, configure/build/test/package |','| Ninja | 1.13.2 | Official release digest, actual build |','| Git / Git LFS | 2.49.0.windows.1 / 3.6.1 | Reused; exact version checks |','| Python / PowerShell | 3.13.5 / 7.6.5 | Reused; exact version checks |','| vcpkg | source/baseline `'+sources['vcpkg_commit']+'`; tool 2026-07-27-98d7cb0cf1f4686a3e43aa5672b6230c1d56bce8 | Exact revisions, local tool hash, valid Microsoft signature |','| DXC | v1.9.2609; dxcompiler.dll/dxil.dll 1.9.2609.5 | Same official ZIP; DXIL and SPIR-V compiler smokes |','| FlatBuffers / flatc | 25.12.19 / 25.12.19 | Matching library pin and official compiler; 13 SDK schemas |','| Node / npm | 24.21.0 / 11.19.0 | Official Node artifact checksum and npm lockfiles |','| XMake | 3.1.1 (binary reports +HEAD.3ba37a0d4) | Official release artifact digest; static SDK build |','| Effekseer authoring/runtime | 1.80.7 / 1.80.7 | Matching official release ZIP digests; UI/device not tested |','| glTF Validator | 2.0.0-dev.3.10 | Official Khronos npm package, lockfile and fixture |','| OpenSSL build tools | Strawberry Perl 5.42.2.1; NASM 3.01 | Actual pinned vcpkg recipe hashes |','','vcpkg also uses its pinned CMake 4.4.0/7-Zip 26.02 host-tool recipes; exact used metadata and local hashes are retained in `cmake/vcpkg-host-tools.lock.json`. No global PATH change, Rust, additional engine/IDE installation, or mandatory Vulkan SDK was introduced. A signed Build Tools installer was acquired but not run unattended; the user supplied the installation.','','## Acquired packages and exact pins','','Every named selected public package and all three inactive candidates are acquired. The full actual Windows vcpkg plan and best-effort pre-download completed successfully. All pinned source/cache archives are hash checked; source exceptions include required recursive submodules and LFS checks where declared. Exact source/tool/archive hashes, versioned port trees, transitive features and patch hashes are in `cmake/*.lock.json`, `vcpkg.json`, `dependencies.json` and the evidence logs.','','| Package | Version/revision | M0 result |','|---|---|---|']
    for p in port_inventory:
        lines.append('| '+p['name']+' | '+p['version']+('#'+str(p['port_version']) if p.get('port_version') else '')+' | '+p['status']+'; '+p['integration']+' |')
    for p in source_inventory:lines.append('| '+p['name']+' | `'+p['commit']+'` | '+p['status']+('; inactive' if not p.get('active',True) else '')+' |')
    lines+=['| EOS Windows C SDK | 1.19.2.1 | Acquired, local hashes and valid Epic signature; integration pending |','| Effekseer runtime/editor | 1.80.7 | Acquired matching release artifacts; adapter pending |','| Official TypeScript MCP SDK | 1.32.1 | npm ci + import passed; no bridge endpoint |','| Khronos glTF Validator | 2.0.0-dev.3.10 | npm ci + real fixture passed |','','Diligent compatible Core/Tools revisions come from umbrella commit `'+sources['diligent_umbrella_commit']+'`. The bundled non-docking ImGui is inactive; official matching 1.92.1 docking is the sole planned compiled provider. ImGuizmo uses an approved source route to avoid a second vcpkg ImGui. DiligentFX/samples are excluded. GNS/OpenSSL/protobuf, RmlUi/FreeType, SDK codecs and other private transitive code are covered by actual recipes and notices, without selecting an engine JSON parser.','','Amplitude static Release /MD build/install and CMake import/link/run passed. Its build uses the selected vcpkg providers, matching flatc, and a recorded patch instead of XMake moving package ranges. The CMake wrapper carries required platform/SIMD definitions and LZ4/FlatBuffers/dylib static dependencies. This recipe currently builds AVX2 code; later CPU/device and AudioService qualification is unverified. Amplitude remains the only audio engine, with its internal miniaudio backend. Candidate FLAC remains inactive: this source pin defines a shared plugin, and static registration/seek/loop gates are still pending.','','## Measured native checks','','Commands, exit codes, elapsed seconds and complete relevant logs are retained under `docs/implementation/evidence/`. Times describe this machine/run and are not promised rebuild budgets.','','| Configuration | Configure s | Build s | CTest s | No-change s | Incremental s | Result |','|---|---:|---:|---:|---:|---:|---|']
    for name,rows in native.items():
        values={r['gate']:r for r in rows}
        seconds=lambda gate:str(values[gate]['seconds'])
        lines.append('| '+name+' | '+seconds('configure')+' | '+seconds('build')+' | '+seconds('ctest')+' | '+seconds('no-change-build')+' | '+seconds('incremental-build')+' | Exit 0, 4/4 tests |')
    lines+=['','All four no-change builds reported `ninja: no work to do`. The controlled change compiled only `engine/runtime/bootstrap.cpp` (dependency scanning and compilation), rebuilt `DarkAngelRuntime.lib` and relinked Headless. Foundation and the three probe sources did not recompile. The original source was restored and rebuilt; the clean checkout remained clean.','','Flecs creates/uses/destroys an isolated world/component. Luau compiles and executes `return 6 * 7` with an interrupt budget and closes the isolated VM. SQLite creates an exclusive temporary fixture, commits a transaction, reads 42 back, closes and deletes it. Tests have explicit diagnostics and timeouts, and retain checks in optimized builds.','','Both final bootstrap acquisition runs returned exit 0 for every step. Each validates existing archive/extracted-file hashes and source pins, installs exact npm lockfiles and performs audited full-graph prefetch without revision updates or cache deletion. The corrected prefetch command waits for a competing vcpkg operation instead of failing immediately. The initial missing compiler and failed compiler activation/cache setup were corrected before these final checks; the known failed CMake cache was preserved before a targeted `--fresh` reset.','','| Bootstrap acquisition | Elapsed s | Steps | Result |','|---|---:|---:|---|',f'| Final first | {round(sum(x["seconds"] for x in first),3)} | {len(first)} | Every exit code 0 |',f'| Final second / idempotence | {round(sum(x["seconds"] for x in second),3)} | {len(second)} | Every exit code 0 |','','Offline checks also passed: tool/source hashes, exact reused/native toolchain versions, EOS input inventory, preset schema, official MCP import, glTF validation fixture, DXIL/SPIR-V compilation, matching schema compilation and docking presence. These are tool/input checks, not later engine adapter acceptance.','','## Stage and package','','The HeadlessShell install component stages exactly three files. Release/RelWithDebInfo package output directories are separate; Debug packaging is excluded from the supported verification profile. Actual Release PE imports were inspected: only Windows API sets, KERNEL32 and MSVC/UCRT runtime imports occur. No renderer/audio/editor/EOS DLL is required by the shell. The observed x64 runtime DLL version is 14.51.36247.0; a compatible serviced Visual C++ Redistributable is an external prerequisite.','','The CPack ZIP was extracted into a separate directory, audited against `cmake/runtime-inventory.json`, and launched from the TEMP directory with development PATH removed. The clean package was copied byte-for-byte to `'+package['file']+'` for delivery. SHA256: `'+package['sha256']+'`. Its console identifies clean source revision `'+clean['source_commit'][:12]+'`.','','## Blockers and remaining gates','','No M0 blocker remains. Acquired later libraries are not described as integrated merely because probes compile. Renderer/D3D12/Vulkan device behavior, EOS/GNS sessions, Jolt/Ozz runtime, RmlUi surfaces, BT.CPP execution, Effekseer adapter/authoring round trips, audio devices/banks/codecs, candidate acceptance, Shipping endpoints/content closure and clean-machine qualification remain their later architecture gates. Debug Amplitude /MDd is prepared but not built/validated in this pass.','','508 acquired-source/tool/candidate notice records were collected from actual inputs; EOS notice files are inventoried without redistributing the entire SDK. The inventory is not a blanket redistribution/license certification, and engine source licensing remains a product decision.','','## Next M1 task','','Implement stable IDs and owned reflection/versioned serialization metadata backed by Flecs Meta, WorldDomain/epoch/generation handles, explicit single-threaded phases and staged writes, bounded work/authority roles, and one declared typed Luau object behavior. Select a native JSON parser deliberately through a recorded M1 choice. Prove stale/wrong-domain rejection, independent world/script state and failed reload preserving the old generation. Do not begin gameplay or renderer implementation as part of M0.']
    (docs/'M0_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    status=['# Implementation status','','M0 is **Verified** on native Windows x64. No M0 blocker remains. Full evidence, exact pins and limitations are in [M0 report](M0_REPORT.md), [dependency inventory](dependencies.json) and [verification receipts](evidence/verification.json).','','| Milestone | Status | Evidence / remaining gate |','|---|---|---|','| M0 project and dependencies | Verified | Three profiles each 4/4 CTest; clean source checkout 4/4; repeat acquisition; rebuild and relocated package checks; static /MD SDK import proof |','| M1 foundation and script world | Not started | IDs, metadata, domains, phases, typed bounded Luau, deliberate JSON parser choice |','| M2 assets and editor shell | Not started | Cook/catalog, Diligent D3D12 and early Vulkan, authoring/undo |','| M3 sessions and agent foundation | Not started | LocalLoopback/GNS/EOS and scoped official MCP bridge |','| M4 character simulation | Not started | Jolt motor and authority/prediction gates |','| M5 animation and combat | Not started | Ozz, Animation Graph/Action Composer and native combat |','| M6 world state and NPCs | Not started | Streaming/ledger, Recast and BT.CPP adapter |','| M7 VFX and audio | Not started | Effekseer and Amplitude service/device/authoring lifecycle gates |','| M8 saves and campaign | Not started | Coherent host SQLite checkpoints/migrations |','| M9 release slice | Not started | Shipping closure, clean-machine, multiplayer/device qualification |','','The full selected stack is acquired; heavy subsystem and inactive-candidate acceptance remains unverified. Source and device acquisition never imply game/runtime integration. Engine Headless links only its small static Foundation/Runtime shell; dependencies are exercised by isolated probes. No gameplay implementation or production editor/agent/audio service is present.','','Reproduce with [bootstrap instructions](BOOTSTRAP.md). Continue with the M1 task described at the end of the M0 report.']
    (docs/'STATUS.md').write_text('\n'.join(status)+'\n',encoding='utf-8')
    print('M0 Verified; wrote status, full pins/inventory and measured evidence')

if __name__=='__main__':main()
